from PIL import Image
from pathlib import Path
import json
root=Path('art/sdp-card-set-01');source=Image.open('art/sdp-asset-pilot/reference-dashboard.png');scale=source.width/390
rows=[
('01-welcome','Welcome card',[22,56,371,149],'21:9','Preserve the wine title band, vanilla body, clipped lower-right corner and original outer border. Remove the Elmina illustration because the already approved separate illustration will be overlaid live.','welcome'),
('02-open-reports','Open reports ticket',[22,161,134,226],'16:9','Preserve the cherry red face, stepped corners, gold inset rim, wine outlines and narrow footer divider.','metric'),
('03-in-progress','In progress ticket',[139,161,253,226],'16:9','Preserve the gold face, stepped corners, vanilla inset rim, wine outlines and narrow footer divider.','metric'),
('04-upcoming-activities','Upcoming activities ticket',[258,161,371,226],'16:9','Preserve the vanilla face, stepped corners, sand inset rim, wine outlines and narrow footer divider.','metric'),
('05-attention-panel','Needs attention outer panel',[22,236,371,460],'3:2','Keep ONLY the outer vanilla panel with its wine outline and folded top-right/lower-right corners. Remove both nested report cards entirely; the interior must be empty vanilla.','panel'),
('06-priority-report','Priority report ticket',[35,263,358,376],'21:9','Preserve the thick cherry ticket frame, stepped/scalloped corners, hanging cherry bookmark at upper left, small blank Priority ribbon above the top-right edge and integrated GOLD bottom action strip. Remove the lettering inside the ribbon and action strip.','report'),
('07-secondary-report','Secondary report ticket',[35,377,358,451],'21:9','Preserve the vanilla face, layered wine keylines, bracket-like corners, two hanging cherry bookmarks at the upper left/right and the slim vertical divider at left.','report'),
('08-upcoming-event','Upcoming event ticket',[22,464,371,540],'21:9','Preserve the elongated vanilla event ticket, semicircular/stepped side notches, gold outer rim and narrow gold heading strip across its top.','event'),
('09-manage-activities','Manage activities card',[22,541,226,635],'21:9','Preserve the gold face, double wine outlines, vanilla/sand inset rim and folded/clipped lower-right corner.','shortcut'),
('10-world-editor','World editor card',[234,541,371,635],'3:2','Preserve the vanilla face, double wine outlines, gold/sand inset rim and folded/clipped lower-right corner.','shortcut')]
items=[]
for i,(id,name,bounds,ratio,detail,kind) in enumerate(rows):
    box=[round(v*scale) for v in bounds];source.crop(box).save(root/'references'/f'{id}.png')
    prompt=f'''REFERENCE-FAITHFUL UI FRAME EXTRACTION — {name}. The supplied crop is the exact master for this ONE card. Produce ONE isolated BLANK decorative card backing, preserving its original silhouette, width-to-height proportions, border thicknesses, corner steps, folds, divider placement, colours and hard offset shadow. {detail} Remove ALL text, numbers, letters, icons, photographs and illustrations, including tiny Sample data text. Reconstruct clean surface underneath removed content. Do not create a dashboard, a collage, a second card, a caption, a label, a logo or any new ornament. The retained frame is decorative; real text, numbers, illustrations and controls will be overlaid in code. Use only wine #6C1A21, cherry #B92C2C, gold #CEA257, sand #D1BF9A and vanilla #E5E0CD. Flat crisp pixel-sticker edges; no blur, no glow, no gradients, no perspective. Preserve this crop's card proportions independently of the output canvas: center the whole card with transparent padding wherever needed, never stretch it to fill the canvas. True alpha transparency outside its silhouette. Keep the entire border, shadow, folds and bookmarks inside the output without clipping.'''
    items.append({'index':i,'id':id,'name':name,'kind':kind,'reference_bounds_390':bounds,'reference_crop_full_resolution':box,'reference_path':str((root/'references'/f'{id}.png').resolve()),'native_size':[bounds[2]-bounds[0],bounds[3]-bounds[1]],'params':{'model':'gpt_image_2_5','variant':'flare','quality':'high','resolution':'1k','background':'transparent','aspect_ratio':ratio,'count':1,'prompt':prompt}})
(root/'catalog.json').write_text(json.dumps({'date':'2026-10-22','scope':'Ten reference-faithful card backings and live review previews; no automatic dashboard replacement','source_job_id':'cf2f2407-8d7f-41b3-9622-052b49ec2ba0','items':items},indent=2),encoding='utf-8')
print('Prepared 10 named source crops and exact single-card generation briefs.')
